-- HEAIL HR question bank seed — Part 5 of 7 (Assessment 5: Leadership, Strategic Alignment and Stakeholder management)
-- Generated from HEAIL_Master.xlsx. Run all 7 parts, in any order, in the same
-- database, after hr_taxonomy_seed.sql (each question references a competency code
-- seeded there). Idempotent: safe to re-run, upserts on primary key.
-- 795 questions.

BEGIN;

ON CONFLICT (question_id) DO UPDATE SET
  competency_code = EXCLUDED.competency_code,
  question_type = EXCLUDED.question_type,
  text = EXCLUDED.text,
  option_a = EXCLUDED.option_a,
  option_b = EXCLUDED.option_b,
  option_c = EXCLUDED.option_c,
  option_d = EXCLUDED.option_d,
  option_e = EXCLUDED.option_e,
  score_a = EXCLUDED.score_a,
  score_b = EXCLUDED.score_b,
  score_c = EXCLUDED.score_c,
  score_d = EXCLUDED.score_d,
  score_e = EXCLUDED.score_e,
  active = EXCLUDED.active;

COMMIT;
